import{_ as a,a as e}from"./chunks/08-model-settings.wwAq27Vh.js";import{_ as r}from"./chunks/02-model-link-create.GYs-TGFF.js";import{_ as o,o as i,c as n,a2 as l}from"./chunks/framework.z3u3TMv0.js";const b=JSON.parse('{"title":"模型連接與參數","description":"MiniTavern BYOK 模型連接教程：填寫 Base URL 與 API Key、測連、採樣參數；對接雲端或 Ollama/LM Studio 本地 OpenAI 兼容接口。","frontmatter":{"title":"模型連接與參數","description":"MiniTavern BYOK 模型連接教程：填寫 Base URL 與 API Key、測連、採樣參數；對接雲端或 Ollama/LM Studio 本地 OpenAI 兼容接口。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"模型連接與參數 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern BYOK 模型連接教程：填寫 Base URL 與 API Key、測連、採樣參數；對接雲端或 Ollama/LM Studio 本地 OpenAI 兼容接口。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/manual/model-link"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/manual/model-link"}]]},"headers":[],"relativePath":"zh-TW/manual/model-link.md","filePath":"zh-TW/manual/model-link.md","lastUpdated":1787224147000}'),d={name:"zh-TW/manual/model-link.md"};function s(p,t,h,u,c,m){return i(),n("div",null,[...t[0]||(t[0]=[l('<h1 id="模型連接與參數" tabindex="-1">模型連接與參數 <a class="header-anchor" href="#模型連接與參數" aria-label="Permalink to &quot;模型連接與參數&quot;">​</a></h1><p>BYOK：密鑰保存在本機安全存儲；請求直連你配置的地址。</p><p>沒有付費 API 時，可先看 <a href="/ultra_guides/zh-TW/free-cloud/">免費雲端</a>；本機部署見 <a href="/ultra_guides/zh-TW/local/">部署本地模型</a>。</p><h2 id="模型連接" tabindex="-1">模型連接 <a class="header-anchor" href="#模型連接" aria-label="Permalink to &quot;模型連接&quot;">​</a></h2><p>路徑：<strong>設置 → 模型 → 模型連接</strong></p><p><img src="'+a+'" alt="模型連接列表"></p><table tabindex="0"><thead><tr><th>操作</th><th>說明</th></tr></thead><tbody><tr><td>新建</td><td>平臺、密鑰、Base URL、模型</td></tr><tr><td>編輯 / 複製 / 刪除</td><td>列表右側菜單</td></tr><tr><td>設為默認</td><td>新對話默認使用</td></tr><tr><td>測連</td><td>保存前或編輯頁「測試」。須選<strong>文本聊天</strong>模型；TTS / 生圖專用 ID（如 Gemini <code>*-tts</code>）會報不支持文字對話，見 <a href="./errors#textoutputunsupported">錯誤排錯 · textOutputUnsupported</a></td></tr></tbody></table><h3 id="平臺類型-常見" tabindex="-1">平臺類型（常見） <a class="header-anchor" href="#平臺類型-常見" aria-label="Permalink to &quot;平臺類型（常見）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>選項（文案以 App 為準）</th><th>用途</th></tr></thead><tbody><tr><td>各雲廠商預設</td><td>自動填國內/國際站 Base URL</td></tr><tr><td>自定義 (OpenAI 協議)</td><td>本地 Ollama / LM Studio、兼容網關</td></tr><tr><td>自定義 Gemini / Anthropic</td><td>對應協議端點</td></tr></tbody></table><p>多站點平臺可切換「使用國際站」。本地模型詳見 <a href="/ultra_guides/zh-TW/connect-app/minitavern">連接 MiniTavern</a> 與 <a href="/ultra_guides/zh-TW/local/tools">工具總覽</a>。</p><p><img src="'+r+'" alt="新建連接"></p><h2 id="模型設置-全局參數" tabindex="-1">模型設置（全局參數） <a class="header-anchor" href="#模型設置-全局參數" aria-label="Permalink to &quot;模型設置（全局參數）&quot;">​</a></h2><p>路徑：<strong>設置 → 模型設置</strong></p><p><img src="'+e+'" alt="模型設置"></p><p>常見項（名稱以 App 為準）：</p><ul><li>記憶長度（歷史條數相關）</li><li>回覆令牌（max tokens，上限 128000；部分 Claude 場景<strong>不要</strong>設為 None）</li><li>Temperature、Top-P / Top-K</li><li>是否流式輸出</li></ul><h2 id="會話級覆蓋" tabindex="-1">會話級覆蓋 <a class="header-anchor" href="#會話級覆蓋" aria-label="Permalink to &quot;會話級覆蓋&quot;">​</a></h2><p>路徑：對話頁 → <strong>設置</strong> → 模型連接 / 參數</p><p>可為單聊指定連接與採樣，不改全局默認。</p><h2 id="聊天設置裡的識圖" tabindex="-1">聊天設置裡的識圖 <a class="header-anchor" href="#聊天設置裡的識圖" aria-label="Permalink to &quot;聊天設置裡的識圖&quot;">​</a></h2><p>路徑：<strong>設置 → 聊天 → 識圖設置</strong></p><p>單聊可在聊天設置 → <strong>識圖與顯示</strong> 跟隨默認或單獨覆蓋（描寫模型與提示詞仍用全局）。</p><ul><li>關閉「圖片描寫」：多模態直接把圖送給模型（模型需支持視覺）。</li><li>開啟：僅噹噹前聊天主模型<strong>不支持</strong>圖片參數時生效——先由描寫模型圖轉文（可與識人同一次請求），再發主模型；描寫結果會緩存複用。主模型已支持視覺時仍多模態直傳，此開關不攔截。</li></ul><p>不支持圖片的主模型 + 開啟描寫後的發送順序：描寫（+識人）→ 主聊天（若開了智能/關鍵詞回覆出圖會附帶生圖提示詞）→ 若回覆帶生圖數據再旁路生圖。</p><p>若報「當前模型不支持圖片」，見 <a href="./errors#visionunsupported">錯誤排錯 · visionUnsupported</a>。</p><h2 id="生圖-連接-回覆圖片-關鍵詞" tabindex="-1">生圖（連接 / 回覆圖片 / 關鍵詞） <a class="header-anchor" href="#生圖-連接-回覆圖片-關鍵詞" aria-label="Permalink to &quot;生圖（連接 / 回覆圖片 / 關鍵詞）&quot;">​</a></h2><p>路徑：<strong>設置 → 生圖</strong></p><ul><li><strong>生圖連接 / 生圖設置</strong>：API、尺寸/質量、生成數量（僅 <code>/imagine</code>）、增強/負面提示詞（僅 <code>/imagine</code> 與附件菜單生圖；默認畫質詞 / 低質量·模糊·多餘手指·水印等）</li><li><strong>回覆圖片</strong>（在生圖設置裡）：先打開開關，再選觸發方式。關閉後聊天不會自動出圖（斜槓命令、附件菜單、長按氣泡不受影響） <ul><li><strong>智能判斷</strong>：由模型根據對話判斷這一輪要不要出圖；畫幅按場景選（手機自拍 3:4，相機成片 3:2），命中後固定 1 張。可附圖發送（例如「拍張這種風格的」），附圖作風格參考，不替代角色/用戶身份圖判定</li><li><strong>關鍵詞觸發</strong>：用戶消息命中關鍵詞規則時出圖（可附圖）；畫面和畫幅按當前對話生成，命中後固定 1 張</li></ul></li><li><strong>關鍵詞觸發生圖</strong>：配置規則。要真正觸發，需在生圖設置中開啟回覆圖片並選擇關鍵詞觸發</li></ul><p>聊天裡生圖：</p><table tabindex="0"><thead><tr><th>入口</th><th>說明</th></tr></thead><tbody><tr><td><code>/imagine 提示詞</code></td><td>先經主聊天模型判斷：是否與當前對話有關、要不要角色/用戶參考圖，再拼提示詞去生圖。可先點加號附圖：主模型會看到這些圖再寫生圖提示詞，生圖時也會當作參考；附圖不會讓模型跳過角色圖/用戶圖的判斷。這些圖會顯示在生圖氣泡的小預覽裡，不會當成一條聊天發言。張數用生圖設置裡的「生成數量」。失敗時氣泡會留下並顯示重試</td></tr><tr><td><code>/imagine scene</code> / 附件 → 根據故事</td><td>按近期對話畫當前這一幕，1 張</td></tr><tr><td><code>/imagine last</code> / 附件 → 根據最後消息</td><td>按最後一條消息來畫，1 張</td></tr></tbody></table><p>未配置生圖連接時，附件菜單四種生圖模式與發送 <code>/imagine</code> 會彈出「去設置 / 取消」，不清空輸入框。智能 / 關鍵詞自動出圖則為 Toast。在生圖設置開啟「回覆圖片」時若無連接會彈窗，開關保持關閉。 | 附件 → 生成背景圖 | 畫環境背景，1 張；完成後可設為聊天背景 | | 長按氣泡 → 生圖 | 按這條氣泡來畫，1 張 |</p><p>例子：輸入「給我一張你的自拍照」會帶上角色參考和對話語境；「給我一張小狗的照片」則按獨立請求畫，不套角色臉。</p><p>本機 A1111 / ComfyUI：<a href="/ultra_guides/zh-TW/local/image-gen/">生圖模型部署</a> · <a href="/ultra_guides/zh-TW/local/image-gen/connect-app">連 App</a>。<br> 雲端免費檔見 <a href="/ultra_guides/zh-TW/free-cloud/#免費生圖怎麼配">免費雲端 · 生圖</a>。</p><h2 id="排錯入口" tabindex="-1">排錯入口 <a class="header-anchor" href="#排錯入口" aria-label="Permalink to &quot;排錯入口&quot;">​</a></h2><p>測連或聊天失敗 → Toast / 氣泡 → <strong>查看詳情</strong>（錯誤代碼 + 原因 + 建議）→ 對照 <a href="./errors">錯誤代碼排錯</a>。</p>',35)])])}const f=o(d,[["render",s]]);export{b as __pageData,f as default};
